import{_ as s,l as i,o as e,c as l,v as r,p as n,x as t,d,i as A,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"SHA-3 海绵","description":"","frontmatter":{"title":"SHA-3 海绵","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sha3-sponge.md","filePath":"cs/sha3-sponge.md","lastUpdated":1789023840000}'),p={name:"cs/sha3-sponge.md"};function c(S,a,E,_,m,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="sha-3-海绵" tabindex="-1">SHA-3 海绵 <a class="header-anchor" href="#sha-3-海绵" aria-label="Permalink to &quot;SHA-3 海绵&quot;">​</a></h1><div class="epigraph"><p>海绵把一个宽置换反复用：先吸收消息进状态，再挤出摘要。输出不必等于整个内部状态，长度扩展那类 MD 遗产从结构上被拆掉。</p><footer>—— Bertoni, Daemen, Peeters and Van Assche, Cryptographic sponge functions；NIST FIPS 202</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/merkle-damgard">Merkle–Damgård</a>的链接值即摘要前缀。缺口是<strong>另一族</strong>：Keccak 海绵，SHA-3 与 SHAKE。不重写碰撞三条性质，只换构造。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MD 的最终摘要往往就是链状态（或截断但仍泄漏可继续的状态）。海绵：状态分比率 \\(r\\) 与容量 \\(c\\)，吸收阶段把消息块异或进 \\(r\\)，再做置换 \\(f\\)；挤出阶段读 \\(r\\)。容量不直接输出，长度扩展不再「接着压一块」。缺口是海绵的吸收/挤出，不是再背 SHA-256 圈数。</p><h3 id="shake-是-xof" tabindex="-1">SHAKE 是 XOF <a class="header-anchor" href="#shake-是-xof" aria-label="Permalink to &quot;SHAKE 是 XOF&quot;">​</a></h3><p>挤出可任意长，当 PRG 式派生时要换域分离，避免与哈希同一上下文。</p><p><span class="marginnote">FIPS 202。Keccak 置换是 1600 比特。本课不把 SHA-3 写成「SHA-2 被破所以必须换」——SHA-2 仍广泛安全；SHA-3 是结构多样性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画吸收循环与挤出循环。对比 MD 的单向链。指出 SHAKE128/256 的可变输出。HMAC 对 SHA-3 仍可用，但海绵有 KMAC 更贴结构。</p>',12)),(e(),n(h,null,{default:t(()=>[A(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%B6%88%E6%81%AF%E5%9D%97%22%5D%20--%3E%20ABS%5B%22%E5%90%B8%E6%94%B6%3A%20%E2%8A%95%E8%BF%9B%E6%AF%94%E7%8E%87%E5%86%8D%E7%BD%AE%E6%8D%A2%22%5D%0A%20%20ABS%20--%3E%20ABS%0A%20%20ABS%20--%3E%20SQ%5B%22%E6%8C%A4%E5%87%BA%3A%20%E8%AF%BB%E6%AF%94%E7%8E%87%E5%86%8D%E7%BD%AE%E6%8D%A2%22%5D%0A%20%20SQ%20--%3E%20DIG%5B%22%E6%91%98%E8%A6%81%E6%88%96%20XOF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容量 \\(c\\) 对应安全边际：内部有不输出的部分。这服务抗碰撞与原像，前提是 \\(f\\) 像随机置换。它不自动给 MAC；密钥如何拌进海绵，是域分离问题，下一课与 HMAC 一起收。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Keccak 圈函数的 θρπχι 全套。长度扩展与 HMAC 下一课专门关 MD 遗产，并说明为何「\\(H(k\\|m)\\)」不够。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MD 链状态等于可续写的内部。</li><li>海绵：吸收/挤出，容量不直接输出。</li><li>SHA-3 与 SHAKE 是 FIPS 202；与 SHA-2 并存。</li><li>下一课：长度扩展为何逼出 HMAC。</li><li>出处：Bertoni et al., sponge；NIST FIPS 202。</li></ul>',8))])}const D=s(p,[["render",c]]);export{B as __pageData,D as default};
